package sohal.lld.snakeladder.entity;public abstract class Entity {    private int start;    private int end;    public Entity(int start, int end) {        this.start = start;        this.end = end;    }    public int getEnd() {        return end;    }    public int getStart() {        return start;    }    @Override    public String toString() {        return "Entity{" +                "start=" + start +                ", end=" + end +                '}';    }}